INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (1, 'Thám Tử Lừng Danh Conan: Dư Ảnh Của Độc Nhãn', 'Conan cùng thanh tra Yamato Kansuke điều tra vụ án bí ẩn trên vùng núi tuyết Nagano, hé lộ ký ức bị đánh mất và âm mưu nguy hiểm đằng sau vết thương độc nhãn.', 110, 'Resources\Images\Movies\Conan_2025.jpg', 0, 'Katsuya Shigehara', 'Hành động, Trinh thám, Hoạt hình', '2026-11-07 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (2, 'Doraemon Movie 45: Nobita Và Cuộc Phiêu Lưu Vào Thế Giới Trong Tranh', 'Nhóm bạn Nobita và Doraemon bước qua cánh cổng bảo bối tiến vào vương quốc hội họa thời Trung cổ châu Âu để giải cứu viên ngọc sắc màu huyền thoại.', 105, 'Resources\Images\Movies\Doraemon_movie45.jpg', 0, 'Yukiyo Teramoto', 'Hoạt hình, Phiêu lưu, Gia đình', '2026-11-13 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (3, 'Godzilla Minus One: Godzilla Trừ Không', 'Nhật Bản thời hậu chiến đứng trước bờ vực sụp đổ hoàn toàn khi siêu quái thú khổng lồ Godzilla trỗi dậy từ đáy đại dương với sức hủy diệt kinh hoàng.', 125, 'Resources\Images\Movies\Godzilla_Trừ_Không.jpg', 0, 'Takashi Yamazaki', 'Hành động, Viễn tưởng, Kịch tính', '2026-10-31 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (4, 'Tử Chiến Trên Không', 'Chuyến bay định mệnh ở độ cao 10.000 mét biến thành cuộc đấu trí nghẹt thở từng giây giữa lực lượng an ninh hàng không và nhóm không tặc táo tợn.', 118, 'Resources\Images\Movies\Tu_chien_tren_khong.jpg', 0, 'Hàm Trần', 'Hành động, Giật gân', '2026-11-16 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (5, 'Tom & Jerry: Quậy Tung New York', 'Cặp đôi mèo chuột huyền thoại Tom và Jerry gây náo loạn khách sạn sang trọng bậc nhất New York ngay trước thềm đám cưới thế kỷ.', 101, 'Resources\Images\Movies\Tom_And_Jerry.jpg', 0, 'Tim Story', 'Hoạt hình, Hài hước, Gia đình', '2026-10-26 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (6, 'Thám Tử Lừng Danh Conan Movie 29: Ngôi Sao Bí Ẩn', 'Siêu đạo chích Kaito Kid gửi mật thư thách thức toàn bộ sở cảnh sát Tokyo xoay quanh báu vật thiên văn cổ đại. Mở bán vé sớm suất chiếu đặc biệt!', 115, 'Resources\Images\Movies\Poster_Conan_Movie_29.jpg', 1, 'Yuzuru Tachikawa', 'Trinh thám, Hoạt hình, Hành động', '2026-11-30 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (7, 'Chiến Binh Ngân Hà: Kỷ Nguyên Mới', 'Hành trình vượt qua hố đen vũ trụ của hạm đội tiên phong nhân loại nhằm tìm kiếm hành tinh sự sống mới trước thảm họa diệt vong.', 135, 'Resources\Images\Movies\Godzilla_Trừ_Không.jpg', 1, 'Denis Villeneuve', 'Khoa học viễn tưởng, Hành động', '2026-12-05 00:00:00');
INSERT INTO "Movies" ("Id", "Title", "Description", "DurationMinutes", "PosterUrl", "Status", "Director", "Genre", "ReleaseDate") VALUES (8, 'Doraemon: Nobita Và Đảo Giấu Vàng', 'Chuyến hải trình vượt Thái Bình Dương trên con tàu Vinh Quang của Nobita để khám phá bí mật hòn đảo kho báu.', 109, 'Resources\Images\Movies\2018-doraemon-movie-poster.jpg', 2, 'Kazuaki Imai', 'Hoạt hình, Phiêu lưu', '2026-08-27 00:00:00');
